(function(){'use strict';if(!window.WCSUC||!WCSUC.ajaxUrl||!WCSUC.nonce)return;var state={opened:false,loading:false,attempted:false,closed:false};function qs(selector,root){return(root||document).querySelector(selector)}function isVisible(el){if(!el)return false;var style=window.getComputedStyle(el);return style.display!=='none'&&style.visibility!=='hidden'&&parseFloat(style.opacity||'1')>0}function elementorPopupIsOpen(){var popups=document.querySelectorAll('.elementor-popup-modal');for(var i=0;i<popups.length;i++){if(isVisible(popups[i]))return true}return false}function createShell(){if(qs('#wc-suc-overlay'))return qs('#wc-suc-overlay');var overlay=document.createElement('div');overlay.id='wc-suc-overlay';overlay.className='wc-suc-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-hidden','true');overlay.innerHTML='<div class="wc-suc-modal" role="document"><button type="button" class="wc-suc-close" data-wc-suc-close aria-label="بستن"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"></path></svg></button><header class="wc-suc-header"><h2></h2><p></p></header><div class="wc-suc-products" data-wc-suc-products><div class="wc-suc-loading" aria-hidden="true"><span></span><span></span><span></span></div></div><div class="wc-suc-footer"><button type="button" class="wc-suc-continue" data-wc-suc-close>ادامه تکمیل سفارش</button></div></div>';document.body.appendChild(overlay);bindCloseEvents(overlay);return overlay}function bindCloseEvents(overlay){var closeButtons=overlay.querySelectorAll('[data-wc-suc-close]');for(var i=0;i<closeButtons.length;i++){closeButtons[i].addEventListener('click',closeModal)}overlay.addEventListener('click',function(event){if(event.target===overlay)closeModal()})}function setText(overlay){var title=overlay.querySelector('.wc-suc-header h2');var subtitle=overlay.querySelector('.wc-suc-header p');if(title)title.textContent='پیشنهادهای تکمیلی برای خرید شما';if(subtitle)subtitle.textContent='برای تکمیل خریدتان، این محصولات هم ممکن است به کارتان بیاید.'}function openModal(overlay){if(state.closed||elementorPopupIsOpen())return;state.opened=true;overlay.classList.add('is-open');overlay.setAttribute('aria-hidden','false');document.documentElement.classList.add('wc-suc-open');document.body.classList.add('wc-suc-open')}function closeModal(){var overlay=qs('#wc-suc-overlay');state.closed=true;if(!overlay)return;overlay.classList.remove('is-open');overlay.setAttribute('aria-hidden','true');document.documentElement.classList.remove('wc-suc-open');document.body.classList.remove('wc-suc-open')}function loadRecommendations(overlay){if(state.loading||state.attempted||state.closed)return;state.loading=true;state.attempted=true;var products=overlay.querySelector('[data-wc-suc-products]');if(products)products.innerHTML='<div class="wc-suc-loading" aria-hidden="true"><span></span><span></span><span></span></div>';var data=new FormData();data.append('action','wc_suc_recommendations');data.append('nonce',WCSUC.nonce);data.append('count',String(WCSUC.count||4));fetch(WCSUC.ajaxUrl,{method:'POST',credentials:'same-origin',body:data,cache:'no-store'}).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.json()}).then(function(json){state.loading=false;if(!json||!json.success||!json.data||!json.data.html){if(overlay&&overlay.parentNode)overlay.parentNode.removeChild(overlay);return}if(!products)return;products.innerHTML=json.data.html;openModal(overlay)}).catch(function(){state.loading=false;if(overlay&&overlay.parentNode)overlay.parentNode.removeChild(overlay)})}function start(){if(state.attempted)return;if(!document.body)return;if(document.body.classList.contains('woocommerce-order-received'))return;if(elementorPopupIsOpen())return;var overlay=createShell();setText(overlay);window.setTimeout(function(){loadRecommendations(overlay)},Math.max(0,parseInt(WCSUC.delay||650,10)))}document.addEventListener('keydown',function(event){if(event.key==='Escape'&&state.opened)closeModal()});document.addEventListener('elementor/popup/show',function(){if(state.opened)closeModal()});if(document.body)document.body.addEventListener('updated_checkout',function(){if(state.opened)closeModal()});if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',start,{once:true})}else{start()}})();